    "type": "short_answer",
    "text": "为什么说人民民主是社会主义的生命？",
    "answer": "（1）民主是全人类共同价值，是人类政治文明发展的成果。（2）民主是中国共产党和中国人民始终不渝坚持的重要理念。（3）人民民主建立在社会主义经济基础之上，体现了社会主义国家的性质，反映了社会主义制度的本质要求，是一种新型的社会主义民主。（4）人民民主是全面建设社会主义现代化国家的应有之义。历史和实践证明，人民民主是社会主义的生命，没有民主就没有社会主义，就没有社会主义的现代化，就没有中华民族伟大复兴。",
