    "answer": "（1）全过程人民民主植根于我国社会主义民主的长期实践，是中国特色社会主义民主政治理论和实践的重大成果。（2）全过程人民民主是新时代我国民主政治领域具有重大创新意义的标志性成果。（3）全过程人民民主是过程民主和成果民主的统一。（4）全过程人民民主是程序民主和实质民主的统一。（5）全过程人民民主是直接民主和间接民主的统一。（6）全过程人民民主是人民民主和国家意志的统一。",
