    "text": "简述公有制经济的主体地位。",
    "answer": "公有制经济的主体地位：（1）公有制经济是全体人民的宝贵财富，公有制主体地位不能动摇，国有经济主导作用不能动摇，这是我国各族人民共享发展成果的制度性保证，也是巩同党的执政地位、坚持我国社会主义制度的重要保证。（2）必须坚持公有制主体地位，探索公有制多种实现形式，发挥国有经济战略支撑作用，推进国有经济布局优化和结构调整，增强国有经济竞争力、创新力、控制力、影响力、抗风险能力。（3）国有企业是中国特色社会主义的重要物质基础和政治基础，是我们党执政兴国的重要支柱和依靠力量。",
