    "answer": "促进区域协调发展，是贯彻新发展理念的重要内容，也是实现高质量发展的必然要求。（1）要深入实施区域协调发展战略、区域重大战略、主体功能区战略。（2）要推进以人为核心的新型城镇化，加快农业转移人口市民化。（3）促进区域协调发展，不能简单要求各地区在经济发展上达到同一水平，而是要根据各地区的条件，走合理分工、优化发展的路子。",
